import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, interpolateColors, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type InstagramProfileCardProps = Record<string, any>;

const InstagramProfileCard: React.FC<InstagramProfileCardProps> = ({
  backgroundColor = "#f9fafb",
  transparentBackground = true,
  durationInSeconds = 5,
  profileImage = "https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?q=80&w=600&auto=format&fit=crop",
  username = "hazzytrainer",
  name = "Neymul Hassan Islam",
  bio = "Fitness Trainer\n🔱 16+ Years Natural Training\n🔥 1100+ Cultured Men Transformed\n🪔... more",
  postsCount = 1699,
  followersText = "1.2M",
  followingCount = 354,
  verifiedBadgeColor = "#3b82f6"
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Base scaling to ensure responsiveness across different canvas sizes (optimized for 1080 wide)
  const baseScale = width / 1080;

  // Animations
  const enterScale = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 }
  });

  const rotationProgress = spring({
    frame,
    fps,
    config: { damping: 20, stiffness: 60 }
  });

  // 3D Tilted Entry and Ambient Float
  const startRotateX = 30;
  const startRotateY = -40;
  const endRotateX = 5;
  const endRotateY = -12;

  const rotateX = interpolate(rotationProgress, [0, 1], [startRotateX, endRotateX]) + Math.sin(frame / 60) * 3;
  const rotateY = interpolate(rotationProgress, [0, 1], [startRotateY, endRotateY]) + Math.cos(frame / 50) * 3;
  
  const floatY = Math.sin((frame - 15) / 40) * 15;
  const floatX = Math.cos((frame - 15) / 50) * 10;

  // Inner Element Animations
  const ringRotation = interpolate(frame, [0, fps * durationInSeconds], [0, 360 * 2]);
  
  const badgeScale = spring({
    frame: frame - 30,
    fps,
    config: { damping: 10, stiffness: 150 }
  });

  // Numbers Tick Up
  const statProgress = spring({
    frame: frame - 25,
    fps,
    config: { damping: 14, stiffness: 40 }
  });

  const currentPosts = Math.round(statProgress * postsCount);
  const currentFollowing = Math.round(statProgress * followingCount);
  
  // Parse followers text (e.g., "1.2M" -> ticks up to 1.2, appends "M")
  const followersMatch = followersText.match(/^([0-9.]+)(.*)$/);
  const followersTargetNum = followersMatch ? parseFloat(followersMatch[1]) : 0;
  const followersSuffix = followersMatch ? followersMatch[2] : '';
  const currentFollowersNum = followersMatch 
    ? (statProgress * followersTargetNum).toFixed(followersTargetNum % 1 === 0 ? 0 : 1) 
    : followersText;

  // Button Press Animation (Following Button)
  const pressDown = spring({ frame: frame - 90, fps, config: { damping: 15, stiffness: 300 } });
  const pressUp = spring({ frame: frame - 98, fps, config: { damping: 12, stiffness: 200 } });
  const clickScale = 1 - (pressDown * 0.05) + (pressUp * 0.05);

  // Button State Transitions
  const isFollowing = frame >= 98;
  const buttonBgColor = interpolateColors(frame, [96, 98], [verifiedBadgeColor, "#efefef"]);
  const buttonTextColor = interpolateColors(frame, [96, 98], ["#ffffff", "#000000"]);

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      fontFamily: interFamily,
      justifyContent: 'center',
      alignItems: 'center',
      perspective: 1500
    }}>
      <div style={{
        transform: `scale(${baseScale}) translate3d(${floatX}px, ${floatY}px, 0) scale(${enterScale}) rotateX(${rotateX}deg) rotateY(${rotateY}deg)`,
        transformStyle: 'preserve-3d',
        width: 880,
        position: 'relative'
      }}>
        
        {/* Ambient Glow */}
        <div style={{
          position: 'absolute',
          inset: -30,
          background: 'linear-gradient(45deg, rgba(220, 39, 67, 0.15), rgba(188, 24, 136, 0.15))',
          filter: 'blur(60px)',
          transform: 'translateZ(-20px)',
          borderRadius: 40,
        }} />

        {/* Main Card Box */}
        <div style={{
          backgroundColor: 'white',
          borderRadius: 40,
          boxShadow: '0 40px 80px rgba(0,0,0,0.1), 0 20px 40px rgba(0,0,0,0.05), inset 0 2px 0 rgba(255,255,255,0.8)',
          width: '100%',
          position: 'relative',
          transformStyle: 'preserve-3d',
          minHeight: 380,
        }}>
          
          {/* Avatar / Profile Container - overlapping edge */}
          <div style={{
            position: 'absolute',
            top: '50%',
            marginTop: -140, // Half of height
            left: -60,
            width: 280,
            height: 280,
            transform: 'translateZ(40px)',
            transformStyle: 'preserve-3d',
          }}>
            {/* Rotating Gradient Ring */}
            <div style={{
              position: 'absolute',
              inset: 0,
              borderRadius: '50%',
              background: 'linear-gradient(45deg, #f09433, #e6683c, #dc2743, #cc2366, #bc1888)',
              transform: `rotate(${ringRotation}deg)`,
              padding: 6,
              boxShadow: '0 20px 40px rgba(0,0,0,0.2)',
            }}>
              <div style={{ width: '100%', height: '100%', backgroundColor: 'white', borderRadius: '50%' }} />
            </div>

            {/* Profile Image inner container */}
            <div style={{
              position: 'absolute',
              inset: 12, // Gap between ring and image
              borderRadius: '50%',
              overflow: 'hidden',
              backgroundColor: '#f3f4f6',
              transform: 'translateZ(10px)',
              boxShadow: 'inset 0 4px 10px rgba(0,0,0,0.1)',
            }}>
              <Img 
                src={profileImage} 
                style={{ width: '100%', height: '100%', objectFit: 'cover' }} 
              />
              {/* Optional ambient tint overlay to simulate anatomy blending if original photo isn't edited */}
              <div style={{
                position: 'absolute',
                inset: 0,
                background: 'linear-gradient(180deg, transparent, rgba(220, 39, 67, 0.1))',
                mixBlendMode: 'overlay',
                pointerEvents: 'none'
              }} />
            </div>
          </div>

          {/* Right Side Content Container */}
          <div style={{
            display: 'flex',
            flexDirection: 'column',
            paddingLeft: 260, // Accommodate the avatar
            paddingRight: 48,
            paddingTop: 48,
            paddingBottom: 48,
            gap: 16,
            transform: 'translateZ(20px)',
            transformStyle: 'preserve-3d',
          }}>
            
            {/* Header: Username + Badge + Dots */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, transform: 'translateZ(10px)' }}>
              <span style={{ fontSize: 36, fontWeight: 800, color: '#000', letterSpacing: '-0.03em' }}>
                {username}
              </span>
              
              <div style={{ transform: `scale(${badgeScale})`, display: 'flex' }}>
                <svg width="28" height="28" viewBox="0 0 24 24" fill="none">
                  <path d="M12 1.5l2.25 1.25L17 2.2l1.35 2.45L21 5.8l-.15 2.75L22.5 11l-1.65 2.45.15 2.75-2.65 1.15L17 19.8l-2.75-.55L12 20.5l-2.25-1.25L7 19.8l-1.35-2.45L3 16.2l.15-2.75L1.5 11l1.65-2.45-.15-2.75L5.65 4.65 7 2.2l2.75.55L12 1.5z" fill={verifiedBadgeColor} />
                  <path d="M9.5 15.5l-3-3 1.4-1.4 1.6 1.6 5.6-5.6 1.4 1.4-7 7z" fill="white" />
                </svg>
              </div>

              <div style={{ marginLeft: 'auto', color: '#000', display: 'flex', alignItems: 'center' }}>
                <svg width="28" height="28" viewBox="0 0 24 24" fill="currentColor">
                  <circle cx="12" cy="5" r="2" />
                  <circle cx="12" cy="12" r="2" />
                  <circle cx="12" cy="19" r="2" />
                </svg>
              </div>
            </div>

            {/* Name */}
            <div style={{ fontSize: 22, fontWeight: 700, color: '#000', marginTop: -8, transform: 'translateZ(10px)' }}>
              {name}
            </div>

            {/* Stats Row */}
            <div style={{ display: 'flex', gap: 28, fontSize: 20, color: '#000', transform: 'translateZ(15px)', marginTop: 4 }}>
              <div>
                <span style={{ fontWeight: 800 }}>{currentPosts.toLocaleString()}</span>{' '}
                <span style={{ color: '#525252', fontWeight: 400 }}>posts</span>
              </div>
              <div>
                <span style={{ fontWeight: 800 }}>{currentFollowersNum}{followersSuffix}</span>{' '}
                <span style={{ color: '#525252', fontWeight: 400 }}>followers</span>
              </div>
              <div>
                <span style={{ fontWeight: 800 }}>{currentFollowing.toLocaleString()}</span>{' '}
                <span style={{ color: '#525252', fontWeight: 400 }}>following</span>
              </div>
            </div>

            {/* Bio */}
            <div style={{ 
              fontSize: 18, 
              color: '#262626', 
              lineHeight: 1.6, 
              whiteSpace: 'pre-wrap', 
              transform: 'translateZ(10px)',
              marginTop: 8
            }}>
              {bio}
            </div>

            {/* Action Buttons */}
            <div style={{ display: 'flex', gap: 12, marginTop: 16, transform: 'translateZ(20px)' }}>
              
              {/* Follow / Following Button (Animates state change) */}
              <div style={{
                flex: 1,
                backgroundColor: buttonBgColor,
                borderRadius: 9999,
                padding: '16px 0',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 8,
                fontSize: 18,
                fontWeight: 700,
                color: buttonTextColor,
                transform: `scale(${clickScale})`,
                boxShadow: clickScale < 1 ? 'inset 0 4px 8px rgba(0,0,0,0.1)' : '0 4px 12px rgba(0,0,0,0.05)',
                transition: 'none'
              }}>
                {isFollowing ? 'Following' : 'Follow'}
                {isFollowing && (
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                    <polyline points="6 9 12 15 18 9"></polyline>
                  </svg>
                )}
              </div>

              {/* Message Button */}
              <div style={{
                flex: 1,
                backgroundColor: '#efefef',
                borderRadius: 9999,
                padding: '16px 0',
                textAlign: 'center',
                fontSize: 18,
                fontWeight: 700,
                color: '#000',
                boxShadow: '0 4px 12px rgba(0,0,0,0.05)',
              }}>
                Message
              </div>

            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default InstagramProfileCard;